export async function listLabelsForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
  if (issueIds.length === 0) return {};

  // The label must be in the same workspace as the join row, not just the
  // issue: a label attached from another workspace never shows on an issue.
  const rows = getDb()
    .select({ issueId: issueLabels.issueId, label: labels })
    .from(issueLabels)
    .innerJoin(
      labels,
      and(eq(labels.id, issueLabels.labelId), orgPredicate(labels.orgId, orgId)),
    )

