/**
 * Checks on what a change points at: assignees, project leads, labels, parent
 * issues and parent comments. Each reference must be usable from the workspace
 * the change is made in. A row that exists in another workspace is refused as a
 * cross-workspace access (tenant scope); one that does not exist, is archived,
 * or is not a current member is refused as not found.
 *
 * Mentions are deliberately not here: they are filtered, never refused.
 */
import { assertOrgScope } from "@/lib/tenant";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { LabelId, OrgId, TenantScoped, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Resolves a row a change points at; `null` means it does not exist anywhere. */
export function requireWorkspaceRow<T extends TenantScoped>(
  actor: Actor,
  row: T | null,
  entity: string,
  id: string,
): T {
  if (row === null) throw new NotFoundError(entity, id);
  assertOrgScope(actor, row.orgId);
  return row;
}

/** Every label must be one of the actor's workspace's own labels. */
export async function requireWorkspaceLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const found = await labelRepo.findLabelsAnyWorkspace(labelIds);
  for (const labelId of labelIds) {
    requireWorkspaceRow(
      actor,
      found.find((label) => label.id === labelId) ?? null,
      "Label",
      labelId,
    );
  }
}

/** Assignees and project leads must be current members of the workspace. */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const current = await memberRepo.listCurrentMemberUserIds(orgId, [userId]);
  if (!current.includes(userId)) throw new NotFoundError("Member", userId);
}

