/**
 * Union of the ids the client supplied (optimistic UI) and the ones parsed out
 * of the body server-side. Only current members survive either route: the
 * handle scan reads active members alone, and client-supplied ids are checked
 * against current membership. Anyone else is dropped silently, never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    status: "active",
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);

  const current = new Set(
    await memberRepo.listCurrentMemberUserIds(orgId, clientProvided),
  );
  const supplied = clientProvided.filter((userId) => current.has(userId));

  return [...new Set([...resolved, ...supplied])];
}

